import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
import { chromium, expect } from '@playwright/test';

const url = pathToFileURL(process.argv[2]).href;
const browser = await chromium.launch();
try {
  const context = await browser.newContext({ offline: true, colorScheme: 'dark', permissions: ['clipboard-read', 'clipboard-write'] });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  page.on('console', message => { if (message.type() === 'error') errors.push(message.text()); });
  await page.goto(url);
  assert.deepEqual(await page.locator('.brand img').evaluate(image => [image.naturalWidth, image.naturalHeight, image.width, image.height]), [128, 128, 28, 28]);
  await expect(page.getByRole('heading', { name: 'Library', exact: true })).toBeVisible();
  await page.getByRole('link', { name: '3 Requests', exact: true }).click();
  await expect(page.locator(':target')).toHaveText('Request directory');
  await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark');
  const catalog = page.locator('.directory[data-folder="Store / Catalog"]');
  await expect(catalog.getByRole('link', { name: /Find/ })).toBeVisible();
  await catalog.locator('summary').click();
  await expect(catalog.getByRole('link', { name: /Find/ })).toBeHidden();
  await expect(page.getByRole('button', { name: 'Browse contents' })).toBeHidden();
  await page.keyboard.press('/');
  await expect(page.getByRole('searchbox')).toBeFocused();
  await page.getByRole('searchbox').fill('catalog GET');
  await expect(page.locator('#matches a')).toHaveCount(1);
  await expect(page.locator('#matches a')).toContainText('Store / Catalog');
  const methodFilter = page.getByLabel('Filter by method or protocol');
  await methodFilter.selectOption('AI');
  await expect(page.locator('#matches a')).toHaveCount(0);
  await methodFilter.selectOption('GET');
  await expect(page.locator('#matches a')).toHaveCount(1);
  await page.getByRole('searchbox').focus();
  await page.getByRole('searchbox').press('ArrowDown');
  await expect(page.locator('#matches a')).toBeFocused();
  await page.keyboard.press('ArrowUp');
  await expect(page.getByRole('searchbox')).toBeFocused();
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('Escape');
  await expect(page.getByRole('searchbox')).toBeFocused();
  await page.getByRole('searchbox').fill('/books');
  await page.getByRole('searchbox').press('Enter');
  await expect(page.getByRole('heading', { name: 'Find', exact: true })).toBeVisible();
  const sectionLinks = page.getByRole('navigation', { name: 'On this request' });
  await sectionLinks.getByRole('link', { name: 'Saved examples' }).click();
  await expect(page.getByRole('heading', { name: 'Saved examples' })).toBeFocused();
  await expect(page.locator(':target')).toHaveText('Saved examples');
  await page.reload();
  await expect(page.locator(':target')).toBeVisible();
  const examples = page.locator('article:visible .saved-examples');
  const picker = examples.getByLabel('Choose saved example');
  const current = examples.locator('.example:visible');
  await expect(current).toHaveCount(1);
  await expect(current).toContainText('200 OK');
  await picker.selectOption('1');
  await expect(current).toContainText('No matching book');
  await current.getByRole('button', { name: 'Copy example cURL' }).click();
  assert.match(await page.evaluate(() => navigator.clipboard.readText()), /books\/404/);
  const scenarioHeading = await current.getByRole('heading', { name: 'Missing scenario' }).getAttribute('id');
  await picker.selectOption('0');
  await expect(current).toContainText('page=1');
  await page.goto(url + '#' + scenarioHeading);
  await expect(picker).toHaveValue('1');
  await expect(page.locator(':target')).toBeVisible();
  await picker.selectOption('0');
  const layout = page.locator('article:visible .reading-layout');
  const columns = () => layout.evaluate(node => getComputedStyle(node).gridTemplateColumns.trim().split(/\s+/).length);
  assert.equal(await columns(), 2);
  await page.setViewportSize({ width: 390, height: 844 });
  assert.equal(await columns(), 1);
  await page.setViewportSize({ width: 1280, height: 720 });
  await sectionLinks.getByRole('link', { name: 'Request details' }).click();
  await expect(page.locator(':target')).toHaveText('Request details');
  const requestHeader = page.locator('article:visible .request-header');
  await requestHeader.getByRole('button', { name: 'Copy address' }).click();
  assert.equal(await page.evaluate(() => navigator.clipboard.readText()), '{{baseUrl}}/books');
  const routeToken = page.locator('article:visible .route').first().getByRole('button', { name: 'Inspect variable baseUrl' });
  const popup = page.getByRole('dialog', { name: 'Variable details' });
  await routeToken.hover();
  await expect(popup).toContainText('Request');
  await expect(popup.locator('code')).toHaveText('https://catalog.example');
  await popup.getByRole('button', { name: 'Copy variable value' }).click();
  assert.equal(await page.evaluate(() => navigator.clipboard.readText()), 'https://catalog.example');
  await page.keyboard.press('Escape');
  await expect(popup).toBeHidden();
  const toggle = page.getByRole('switch', { name: 'Show variable values' });
  await toggle.click();
  await expect(routeToken).toHaveText('https://catalog.example');
  const find = page.locator('article:visible');
  const token = name => find.getByRole('button', { name: 'Inspect variable ' + name, exact: true });
  await expect(token('area')).toHaveText('early');
  assert.equal(await token('empty').textContent(), '');
  await token('someKey').hover();
  await expect(popup).toContainText('Hidden value');
  await expect(popup.getByRole('button', { name: 'Copy variable value' })).toHaveCount(0);
  await token('shard').hover();
  assert.deepEqual((await popup.locator('code').allTextContents()).sort(), ['east', 'west']);
  await page.getByLabel('Variable environment').selectOption('preview');
  await expect(token('shard')).toHaveText('east');
  await expect(routeToken).toHaveText('https://catalog.example');
  await requestHeader.getByRole('button', { name: 'Copy address' }).click();
  assert.equal(await page.evaluate(() => navigator.clipboard.readText()), 'https://catalog.example/books');
  await page.getByRole('button', { name: 'Copy cURL' }).click();
  const command = await page.evaluate(() => navigator.clipboard.readText());
  assert.match(command, /--url '\{\{baseUrl\}\}\/books'/);
  assert.doesNotMatch(command, /literal-secret|https:\/\/catalog\.example/);
  await catalog.evaluate(element => { element.open = false; });
  await page.evaluate(() => window.dispatchEvent(new Event('beforeprint')));
  await expect(catalog).toHaveAttribute('open', '');
  await expect(routeToken).toHaveText('{{baseUrl}}');
  await page.evaluate(() => window.dispatchEvent(new Event('afterprint')));
  await expect(catalog).not.toHaveAttribute('open', '');
  await expect(routeToken).toHaveText('https://catalog.example');
  await toggle.click();
  await expect(routeToken).toHaveText('{{baseUrl}}');
  await page.getByRole('link', { name: 'Read about paging' }).click();
  await expect(page.locator(':target')).toHaveText('Paging');
  await page.reload();
  await expect(page.locator(':target')).toBeVisible();
  await expect(page.locator('.entry[aria-current="page"]')).toContainText('Find');
  await page.getByRole('button', { name: 'Switch to light theme' }).click();
  await page.reload();
  await expect(page.locator('html')).toHaveAttribute('data-theme', 'light');
  await page.setViewportSize({ width: 390, height: 844 });
  await page.getByRole('button', { name: 'Browse contents' }).click();
  await page.locator('nav a[href="#variables"]').click();
  await expect(page.locator('#variables')).toBeVisible();
  const variable = page.locator('.var-card').filter({ has: page.getByRole('heading', { name: '{{baseUrl}}' }) });
  await expect(variable).toContainText('Staging');
  await expect(variable).toContainText('https://staging.example');
  await variable.locator('.var-uses summary').click();
  await variable.locator('.var-uses').getByRole('link', { name: 'Find' }).click();
  await expect(page.getByRole('heading', { name: 'Find', exact: true })).toBeVisible();
  assert.equal(await page.evaluate(() => document.documentElement.scrollWidth), 390);
  const search = page.getByRole('searchbox');
  await search.fill('editor.example');
  await search.press('Enter');
  const article = page.locator('article:visible');
  await expect(article.getByRole('heading', { name: 'Write a brief' })).toBeVisible();
  await expect(article).toContainText('OpenAI');
  await expect(article).toContainText('600');
  await article.getByRole('button', { name: 'Inspect variable baseUrl' }).click();
  await expect(popup.locator('code')).toHaveText('https://brief.example');
  await popup.getByRole('link', { name: 'All definitions' }).click();
  await expect(page.locator(':target')).toContainText('{{baseUrl}}');
  await page.goBack();
  await article.getByRole('button', { name: 'Inspect variable title' }).focus();
  await expect(popup).toContainText('No enabled value');
  await page.keyboard.press('Escape');
  const prompt = '\nReview <book> {{title}}.';
  assert.equal(await article.locator('.prompt-section pre').last().textContent(), prompt);
  await article.getByRole('button', { name: 'Copy user message' }).click();
  assert.equal(await page.evaluate(() => navigator.clipboard.readText()), prompt);
  await article.getByRole('link', { name: /Next request.*AI-request/ }).click();
  await expect(article).toContainText('My note.');
  await expect(article).toContainText('No user message saved');
  await expect(article.locator('.route')).toHaveCount(0);
  await expect(article).not.toContainText('address missing');
  assert.equal(await page.evaluate(() => document.documentElement.scrollWidth), 390);
  await page.emulateMedia({ media: 'print' });
  await expect(page.locator('#overview')).toBeVisible();
  await expect(page.locator('article:visible')).toHaveCount(3);
  await expect(page.locator('.example:visible')).toHaveCount(2);
  const snapshot = page.locator('.example .snapshot').first();
  await snapshot.evaluate(node => { node.open = false; });
  await page.evaluate(() => window.dispatchEvent(new Event('beforeprint')));
  await expect(snapshot).toHaveAttribute('open', '');
  await page.evaluate(() => window.dispatchEvent(new Event('afterprint')));
  await expect(snapshot).not.toHaveAttribute('open', '');
  assert.deepEqual(errors, []);
} finally {
  await browser.close();
}
